def narrative():
    """THE DEUTERONOMY WALK 8b (2026-09-20): the chapter's own acts AS HISTORY — TWO acts told only here written ONCE at their own days by RETROGRADE markers
    (the fragments in the ark at Deut 10:2 → the erection's day (2, 1, 1); Aaron's burial at Deut 10:6 → his death (40, 5, 1)), the stretch ENDED by the
    FORWARD marker at 10:12 (the counter's day (40, 11, 1) re-asserted), then FOUR own-day lines with no marker (the laws restated — demand_declared,
    heart_circumcision_commanded, stranger_love_commanded, cleaving_commanded) — on a world with this runner's daemon: 7 writes (the two retrograde statuses
    dated with their lines, the five on Israel), no timer, THREE entities (the ark, aaron, Israel — the written-on parties; a line's subject makes no
    entity, 7b's lesson), the counter at (11, 1), no close, no row, TWO dated lines. Recorded by the sequential run's recorder and stitched onto the tape
    under the three markers the stitcher types. Not a graded cell: the tuple below is a tripwire typed from the design."""
    with contextlib.redirect_stdout(io.StringIO()):
        w = WE.World(era='Deut 10:1-22 on the tape — the fragments and the burial written once at their own days (the retrograde markers at 10:2 and 10:6), the forward marker at 10:12, the four own-day lines (the exodus epoch)', epoch='exodus')
        w.laws = [law_second_tablets]
        w.advance(w.clock.day_in('exodus', 40, 11, 1))
        # THE DAEMON GATE READS LITERAL SUBMITS ONLY — the six lines typed out under their markers; no field named `until`, `days` or `due`
        w.marker('Deut 10:2', w.clock.day_in('exodus', 2, 1, 1), value="and you shall put them in the ark (10:2) — the fragments in the ark TOLD ONLY HERE, dated at the erection's day: Exod 40:20's testimony placed, (2, 1, 1): RETROGRADE after the counter's (40, 11, 1)", placement='reading_placed')
        w.submit({'kind': 'fragments_placed_in_the_ark', 'subject': 'moses', 'into': 'the_ark', 'with': 'the tablets — the second set whole, the first set broken', 'first_telling': "told only here — 10:2's clause, read of both sets by Menachot 99a:12 and Bava Batra 14b:6; Exodus 34:1 has no ark clause, 40:20 places the whole tablets alone", 'case_source': LINES[0][0]})
        w.marker('Deut 10:6', w.clock.day_in('exodus', 40, 5, 1), value="and he was buried there (10:6) — Aaron's burial TOLD ONLY HERE, dated at his death: Num 20:28's (40, 5, 1) from 33:38's ordinals: RETROGRADE after the counter's (40, 11, 1)", placement='reading_placed')
        w.submit({'kind': 'aaron_buried', 'subject': 'aaron', 'place': "there — Moserah in the retelling (10:6), Mount Hor on the tape (Numbers 20:28, 33:38): the OPEN row inside the line's own field", 'first_telling': "told only here — Numbers 20:28 the death, 20:29 the mourning, 33:38-39 the date and the age: never the burial", 'case_source': LINES[1][0]})
        w.marker('Deut 10:12', w.clock.day_in('exodus', 40, 11, 1), value="and now, Israel (10:12) — the speech resumes at its own day: the retrograde stretch of the burial ENDED, the counter's day (40, 11, 1) re-asserted; FORWARD at the same day, 4:25's, 5:32's and 9:21's form")
        w.submit({'kind': 'demand_declared', 'subject': 'israel', 'asked': 'to fear the LORD your God, to walk in all His ways, to love Him, to serve the LORD your God with all your heart and with all your soul, to keep the commandments', 'the_five': "fear, walk, love, serve, keep — 6:13's, 8:6's and 6:5's verbs in one question; 'with all your might' dropped", 'case_source': LINES[2][0]})
        w.submit({'kind': 'heart_circumcision_commanded', 'subject': 'israel', 'command': 'and you shall circumcise the foreskin of your heart (10:16)', 'prohibition': "and your neck you shall not stiffen any more (10:16) — the chapter's one prohibition", 'case_source': LINES[3][0]})
        w.submit({'kind': 'stranger_love_commanded', 'subject': 'israel', 'counterparty': 'the-stranger', 'reason': 'for you were strangers in the land of Egypt (10:19) — the four seats', 'case_source': LINES[4][0]})
        w.submit({'kind': 'cleaving_commanded', 'subject': 'israel', 'the_four': 'fear, serve, cleave, swear (10:20) — 6:13 with the fourth clause added', 'value': 'the scholars (Ketubot 111b:7)', 'case_source': LINES[5][0]})
    writes = len([l for l in w.log if l[0] == 'WRITE'])
    closes = len([e for ent in w.entities.values() for e in ent.ledger if e.get('closed_by')])
    rows = len([l for l in w.log if l[0] == 'ROW'])
    dated = len([l for l in w.log if l[0] == 'EVENT' and l[2].get('dated') is not None])
    return (writes, len([l for l in w.log if l[0] == 'TIMER-SET']), len(w.entities), w.clock.eras['exodus'].date(w.clock.day)[1:], closes, rows, len(w.tables['population']), dated), w


